	if(is_string($xlsx)){$xlsx_path=wp_tempnam('pharmasure-xlsx-test.xlsx');file_put_contents($xlsx_path,$xlsx);$archive=new ZipArchive();$opened=true===$archive->open($xlsx_path,ZipArchive::CHECKCONS);$assert($opened,'XLSX archive passes ZIP integrity validation');if($opened){$required=array('[Content_Types].xml','docProps/core.xml','xl/workbook.xml','xl/styles.xml','xl/worksheets/sheet1.xml','xl/worksheets/sheet2.xml');$missing=array_filter($required,static fn($part)=>false===$archive->locateName($part));$assert(!$missing,'XLSX contains workbook, properties, styles, data and summary parts');$workbook=$archive->getFromName('xl/workbook.xml');$sheet=$archive->getFromName('xl/worksheets/sheet1.xml');$styles=$archive->getFromName('xl/styles.xml');$assert(false!==$workbook&&str_contains($workbook,'Report data')&&str_contains($workbook,'Summary'),'XLSX exposes separate data and summary worksheets');$assert(false!==$sheet&&str_contains($sheet,'state="frozen"')&&str_contains($sheet,'autoFilter'),'XLSX freezes and filters the report header');$assert(false!==$sheet&&str_contains($sheet,'Subtotal (USD)')&&str_contains($sheet,'<v>10</v>'),'XLSX converts minor currency units into formatted major units');$assert(false!==$sheet&&str_contains($sheet,'=FORMULA')&&str_contains($sheet,'t="inlineStr"'),'XLSX keeps formula-like identifiers as inert text');$assert(false!==$styles&&str_contains($styles,'0.00%')&&str_contains($styles,'$&quot;#,##0.00'),'XLSX includes percentage and currency number formats');foreach($required as $part){$xml=$archive->getFromName($part);$assert(false!==$xml&&false!==simplexml_load_string($xml),"XLSX package part $part is well-formed XML");}$archive->close();}wp_delete_file($xlsx_path);}
